examples:
% int64 nanoseconds, cached, only clock-related bits filtered
[tns, m, aux] = gracefoReading.readL1b('MAS1B_2020-01-01_C_04.txt', ...
    'TimeFormat', 'gpsns', 'QualityBitMask', [6 7], 'CacheDir', 'l1bcache');

[t, q, aux] = gracefoReading.readL1b('SCA1B_2020-01-01_C_04.txt');
[ok, stats] = gracefoReading.checkQuaternionNorm(q, aux);
fprintf('max |norm-1| = %.3g, violations: %d\n', stats.maxDeviation, stats.numViolations);

[t, obs, aux] = gracefoReading.readL1b('KBR1B_2020-01-01_Y_04.txt');
[gaps, stats] = gracefoReading.findGaps(t);   % 5 s nominal, auto-estimated
disp(gaps)

files = gracefoReading.findL1bFiles(root, "ACT1B", ...
    'DateRange', [datetime(2020,1,1) datetime(2020,1,31)], 'Satellite', "C");
[t, acc, aux] = gracefoReading.readL1bMulti(files);
